     * @param DeviceTopicFilter|null $filter Selects the device topics to list.
     * @param bool $includeTotalCount Includes the total count for the filter in the
     *     result.
     * @param bool $includeDevice Includes the Device of each item.
     * @param string $cursor The pagination cursor: $nextCursor of the previous page,
     *     empty for the first page.
     * @param int $limit The maximum number of items to return.
     *
     * @return Pending<DeviceTopicListResult>
     */
    public function deviceTopicList(
        ?DeviceTopicFilter $filter = null,
        bool $includeTotalCount = false,
        bool $includeDevice = false,
        string $cursor = '',
        int $limit = 0,
    ): Pending {
        return $this->add(new DeviceTopicListRequest(
            filter: $filter,
            includeTotalCount: $includeTotalCount,
            includeDevice: $includeDevice,
            cursor: $cursor,
            limit: $limit,
        ));
    }

    /**
     * Changes the topics of a device. The device topic
     * list is what decides who gets a push sent to a topic.
     * Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $deviceId The ID of the device. Required.
     * @param string $op The operation: add, remove or set. Required.
     * @param list<string> $topics The topics for the operation.
     * @param string $user An optional ownership guard: the update is applied only if the
     *     device currently belongs to this user. Otherwise the call fails with a
     *     conflict error (or not found if there is no such device).
     *
     * @return Pending<DeviceTopicUpdateResult>
     */
    public function deviceTopicUpdate(
        string $deviceId,
        string $op,
        array $topics = [],
        string $user = '',
    ): Pending {
        return $this->add(new DeviceTopicUpdateRequest(
            deviceId: $deviceId,
            op: $op,
            topics: $topics,
            user: $user,
        ));
    }

    /**
     * Returns a paginated list of user topic
     * subscriptions. Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param UserTopicFilter|null $filter Selects the user topics to list.
     * @param bool $includeTotalCount Includes the total count for the filter in the
     *     result.
     * @param string $cursor The pagination cursor: $nextCursor of the previous page,
     *     empty for the first page.
     * @param int $limit The maximum number of items to return.
     *
     * @return Pending<UserTopicListResult>
     */
    public function userTopicList(
        ?UserTopicFilter $filter = null,
        bool $includeTotalCount = false,
        string $cursor = '',
        int $limit = 0,
    ): Pending {
        return $this->add(new UserTopicListRequest(
            filter: $filter,
            includeTotalCount: $includeTotalCount,
            cursor: $cursor,
            limit: $limit,
        ));
    }

    /**
     * Changes the topics of a user. The change is also
     * applied to the user's registered devices. Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $user The user ID. Required.
     * @param string $op The operation: add, remove or set. Required.
     * @param list<string> $topics The topics for the operation.
     *
     * @return Pending<UserTopicUpdateResult>
     */
    public function userTopicUpdate(
        string $user,
        string $op,
        array $topics = [],
    ): Pending {
        return $this->add(new UserTopicUpdateRequest(
            user: $user,
            op: $op,
            topics: $topics,
        ));
    }

    /**
     * Sends a push notification. The request is
     * queued and sent to the provider by Centrifugo workers.
     * Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param PushRecipient $recipient Who receives the notification. Required.
     * @param PushNotification $notification The notification to send. Required.
     * @param string $uid A unique identifier of the request, can be used to cancel the
     *     push. UUID v4 is recommended; different requests must use different
     *     uids.
     * @param int $sendAt The Unix time in seconds when to send the notification. If
     *     not set, the notification is sent immediately.
     * @param bool $optimizeForReliability Makes processing heavier, but tolerates edge
     *     cases, like not losing inflight pushes when the queue is briefly
     *     unavailable.
     * @param PushLimitStrategy|null $limitStrategy Sets time constraints and rate limits. Only applies
     *     with a filter recipient; devices are then processed one by one
     *     instead of in batches.
     * @param string $analyticsUid The identifier for push notification analytics. If
     *     not set, uid is used.
     * @param array<string, PushLocalization> $localizations Optional per language/locale localizations. Setting
     *     them enables templating.
     * @param bool $useTemplating Enables templating of the notification. Only works
     *     with a filter recipient.
     * @param bool $useMeta Additionally loads device meta while sending, making it
     *     available in templating.
     *
     * @return Pending<SendPushNotificationResult>
     */
    public function sendPushNotification(
        PushRecipient $recipient,
        PushNotification $notification,
        string $uid = '',
        int $sendAt = 0,
        bool $optimizeForReliability = false,
        ?PushLimitStrategy $limitStrategy = null,
        string $analyticsUid = '',
        array $localizations = [],
        bool $useTemplating = false,
        bool $useMeta = false,
    ): Pending {
        return $this->add(new SendPushNotificationRequest(
            recipient: $recipient,
            notification: $notification,
            uid: $uid,
            sendAt: $sendAt,
            optimizeForReliability: $optimizeForReliability,
            limitStrategy: $limitStrategy,
            analyticsUid: $analyticsUid,
            localizations: $localizations,
            useTemplating: $useTemplating,
            useMeta: $useMeta,
        ));
    }

    /**
     * Saves the delivery or interaction status of a
     * push notification to analytics. Experimental. Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $analyticsUid The $analyticsUid of the push notification (as in
     *     SendPushNotificationRequest). Required.
     * @param string $status The status of the push notification: delivered or
     *     interacted. Required.
     * @param string $deviceId The Centrifugo device ID. Required.
     * @param string $msgId The message ID issued by the provider.
     *
     * @return Pending<UpdatePushStatusResult>
     */
    public function updatePushStatus(
        string $analyticsUid,
        string $status,
        string $deviceId,
        string $msgId = '',
    ): Pending {
        return $this->add(new UpdatePushStatusRequest(
            analyticsUid: $analyticsUid,
            status: $status,
            deviceId: $deviceId,
            msgId: $msgId,
        ));
    }

    /**
     * Cancels a delayed push notification (sent with
     * $sendAt). Centrifugo PRO only.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $uid The uid of the push notification to cancel. Required.
     *
     * @return Pending<CancelPushResult>
     */
    public function cancelPush(
        string $uid,
    ): Pending {
        return $this->add(new CancelPushRequest(uid: $uid));
    }

    /**
     * Publishes or updates a key in a map channel.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     * @param string $key The entry key. Required.
     * @param mixed $data The entry data. In the HTTP API it is any JSON value; over GRPC
     *     it may be binary.
     * @param string $b64data Data as base64, for binary over the HTTP API. Centrifugo
     *     decodes it.
     * @param mixed $streamData Currently not used by the server API.
     * @param string $b64streamData Currently not used by the server API.
     * @param array<string, string> $tags Key-value metadata attached to the publication.
     * @param string $idempotencyKey Drops duplicate publications upon retries: a
     *     publication with a key already used in the channel is not applied
     *     again, and its result has the first one's position, with suppressed
     *     set and $suppressReason "idempotency". It acts per channel; keys are
     *     kept for 5 minutes by default. Every map broker - memory, Redis and
     *     PostgreSQL - keeps keys.
     * @param bool $delta Enables delta compression for this publication.
     * @param int $version A per-key version: publications with a version not higher
     *     than the key's current one are suppressed.
     * @param string $versionEpoch Scopes version. A different epoch resets version
     *     comparison.
     * @param int $score Currently not used by the server API.
     * @param string $keyMode Makes the publish conditional: "if_new" writes only if the
     *     key does not exist, "if_exists" only if it exists. Empty always
     *     writes.
     *
     * @return Pending<MapPublishResult>
     */
    public function mapPublish(
        string $channel,
        string $key,
        mixed $data = null,
        string $b64data = '',
        mixed $streamData = null,
        string $b64streamData = '',
        array $tags = [],
        string $idempotencyKey = '',
        bool $delta = false,
        int $version = 0,
        string $versionEpoch = '',
        int $score = 0,
        string $keyMode = '',
    ): Pending {
        return $this->add(new MapPublishRequest(
            channel: $channel,
            key: $key,
            data: $data,
            b64data: $b64data,
            streamData: $streamData,
            b64streamData: $b64streamData,
            tags: $tags,
            idempotencyKey: $idempotencyKey,
            delta: $delta,
            version: $version,
            versionEpoch: $versionEpoch,
            score: $score,
            keyMode: $keyMode,
        ));
    }

    /**
     * Removes a key from a map channel.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     * @param string $key The key to remove. Required.
     * @param string $idempotencyKey Drops duplicate removals upon retries, as it does for
     *     MapPublishRequest: a removal with a key already used in the channel is
     *     not applied again, and its result is suppressed with $suppressReason
     *     "idempotency". Keys are kept for 5 minutes by default.
     *
     * @return Pending<MapRemoveResult>
     */
    public function mapRemove(
        string $channel,
        string $key,
        string $idempotencyKey = '',
    ): Pending {
        return $this->add(new MapRemoveRequest(
            channel: $channel,
            key: $key,
            idempotencyKey: $idempotencyKey,
        ));
    }

    /**
     * Reads the current state of a map channel, with
     * optional pagination.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     * @param string $cursor The pagination cursor from the previous page. Empty starts
     *     from the beginning.
     * @param int $limit The maximum number of entries per page: -1 means no limit, 0
     *     returns only the stream position. Page sizes may exceed it with the
     *     Redis map broker.
     * @param string $key Reads a single entry by exact key. cursor and limit are ignored
     *     when it is set.
     * @param bool $asc Sorts ordered state by score ascending instead of descending.
     *     Ignored for unordered channels.
     * @param int $revisionOffset The offset of the position from a previous state
     *     read, used with $revisionEpoch.
     * @param string $revisionEpoch The epoch of the position from a previous state
     *     read. If the epoch changed, the call fails with an unrecoverable
     *     position error.
     *
     * @return Pending<MapReadStateResult>
     */
    public function mapReadState(
        string $channel,
        string $cursor = '',
        int $limit = 0,
        string $key = '',
        bool $asc = false,
        int $revisionOffset = 0,
        string $revisionEpoch = '',
    ): Pending {
        return $this->add(new MapReadStateRequest(
            channel: $channel,
            cursor: $cursor,
            limit: $limit,
            key: $key,
            asc: $asc,
            revisionOffset: $revisionOffset,
            revisionEpoch: $revisionEpoch,
        ));
    }

    /**
     * Reads the change stream of a map channel.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     * @param int $sinceOffset Returns entries after this offset, used with
     *     $sinceEpoch.
     * @param string $sinceEpoch The epoch of the since position. It must match the
     *     current stream epoch.
     * @param int $limit The maximum number of entries: -1 means no limit, 0 returns
     *     only the stream position.
     * @param bool $reverse Returns entries newest first.
     *
     * @return Pending<MapReadStreamResult>
     */
    public function mapReadStream(
        string $channel,
        int $sinceOffset = 0,
        string $sinceEpoch = '',
        int $limit = 0,
        bool $reverse = false,
    ): Pending {
        return $this->add(new MapReadStreamRequest(
            channel: $channel,
            sinceOffset: $sinceOffset,
            sinceEpoch: $sinceEpoch,
            limit: $limit,
            reverse: $reverse,
        ));
    }

    /**
     * Returns statistics about a map channel.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     *
     * @return Pending<MapStatsResult>
     */
    public function mapStats(
        string $channel,
    ): Pending {
        return $this->add(new MapStatsRequest(channel: $channel));
    }

    /**
     * Removes all state and stream data of a map channel.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the map channel. Required.
     *
     * @return Pending<MapClearResult>
     */
    public function mapClear(
        string $channel,
    ): Pending {
        return $this->add(new MapClearRequest(channel: $channel));
    }

    /**
     * Pushes data for a key directly to clients of a
     * shared poll channel, without waiting for the next poll cycle. Requires
     * versioned mode and publish_enabled on the namespace.
     *
     * Adds the command to the batch: its Pending holds the result once the
     * batch is sent.
     *
     * @param string $channel The name of the shared poll channel. Required.
     * @param string $key The item key. Required.
     * @param mixed $data The item data, delivered to clients as is.
     * @param string $b64data Data as base64, for binary payloads. Centrifugo decodes it.
     * @param int $version The item version, must be >= 1. Required. A version not
     *     higher than the current one within the same epoch is silently dropped.
     * @param string $epoch The channel-level publisher epoch. A change resets per-key
     *     versions and unsubscribes current subscribers with insufficient state.
     *
     * @return Pending<SharedPollPublishResult>
     */
    public function sharedPollPublish(
        string $channel,
        string $key,
        int $version,
        mixed $data = null,
        string $b64data = '',
        string $epoch = '',
    ): Pending {
        return $this->add(new SharedPollPublishRequest(
            channel: $channel,
            key: $key,
            data: $data,
            b64data: $b64data,
            version: $version,
            epoch: $epoch,
        ));
    }
}
